        effective_from as as_of
    from pit_portfolio_company_portfolio_company_detail_scoped
    union distinct
    select distinct
        portfolio_company_hk,
        effective_from as as_of
    from pit_portfolio_company_portfolio_company_observed_scoped
),
pit_portfolio_company_portfolio_company_detail as (
    select
        pit_portfolio_company_spine.portfolio_company_hk as portfolio_company_hk,
