        max(pit_portfolio_company_portfolio_company_detail_stored.effective_from) as portfolio_company_detail_effective_from
    from pit_portfolio_company_spine
    left join pit_portfolio_company_portfolio_company_detail_scoped as pit_portfolio_company_portfolio_company_detail_stored
        on pit_portfolio_company_portfolio_company_detail_stored.portfolio_company_hk = pit_portfolio_company_spine.portfolio_company_hk
        and pit_portfolio_company_portfolio_company_detail_stored.effective_from <= pit_portfolio_company_spine.as_of
    group by pit_portfolio_company_spine.portfolio_company_hk, pit_portfolio_company_spine.as_of
),
pit_portfolio_company_portfolio_company_observed as (
    select
        pit_portfolio_company_spine.portfolio_company_hk as portfolio_company_hk,
        pit_portfolio_company_spine.as_of as as_of,
        max(pit_portfolio_company_portfolio_company_observed_stored.effective_from) as portfolio_company_observed_effective_from
    from pit_portfolio_company_spine
    left join pit_portfolio_company_portfolio_company_observed_scoped as pit_portfolio_company_portfolio_company_observed_stored
        on pit_portfolio_company_portfolio_company_observed_stored.portfolio_company_hk = pit_portfolio_company_spine.portfolio_company_hk
        and pit_portfolio_company_portfolio_company_observed_stored.effective_from <= pit_portfolio_company_spine.as_of
    group by pit_portfolio_company_spine.portfolio_company_hk, pit_portfolio_company_spine.as_of
),
pit_portfolio_company_joined as (
    select
        pit_portfolio_company_spine.portfolio_company_hk as portfolio_company_hk,
        pit_portfolio_company_spine.as_of as as_of,
        pit_portfolio_company_portfolio_company_detail.portfolio_company_detail_effective_from as portfolio_company_detail_effective_from,
        pit_portfolio_company_portfolio_company_observed.portfolio_company_observed_effective_from as portfolio_company_observed_effective_from
    from pit_portfolio_company_spine
    left join pit_portfolio_company_portfolio_company_detail
        on pit_portfolio_company_portfolio_company_detail.portfolio_company_hk = pit_portfolio_company_spine.portfolio_company_hk and pit_portfolio_company_portfolio_company_detail.as_of = pit_portfolio_company_spine.as_of
    left join pit_portfolio_company_portfolio_company_observed
        on pit_portfolio_company_portfolio_company_observed.portfolio_company_hk = pit_portfolio_company_spine.portfolio_company_hk and pit_portfolio_company_portfolio_company_observed.as_of = pit_portfolio_company_spine.as_of
)

